#!/usr/bin/env bash
# 新服务器第四批：白天/夜间两档并发。
# 这台机器只跑分析（网络为主），两档都给 8 条：它与杭州 12 条、主库只做读者面，合计 20 条是实测的拐点（26 条反而回落到 276/h），
# 两档同值：白天也没有别的机器分担，窗口只决定「谁来重启」，不再决定名额（2026-11-07 定档）。
set -euo pipefail

cat > /usr/local/bin/geohot-exec-window.sh <<'SH'
#!/usr/bin/env bash
set -euo pipefail
mode="${1:-day}"
case "$mode" in
  day)   slots=8; conc=8; lanes=8 ;;
  night) slots=8; conc=8; lanes=8 ;;
  *) echo "usage: $0 day|night"; exit 2 ;;
esac
d=/etc/systemd/system/geohot-exec-worker.service.d
install -d -m 755 "$d"
cat > "$d/50-window.conf" <<CONF
# generated by geohot-exec-window.sh at $(date -u +%Y-%m-%dT%H:%M:%SZ) mode=$mode
[Service]
Environment=GEOHOT_INTAKE_LANES=combined
Environment=GEOHOT_INTAKE_ANALYSIS_SLOTS=$slots
Environment=GEOHOT_INTAKE_LANE_LIMIT=$lanes
Environment=GEOHOT_INTAKE_COMBINED_LIMIT=$lanes
Environment=ANALYZE_CONCURRENCY=$conc
Environment=GEOHOT_RESOURCE_PROFILE=balanced
Environment=GEOHOT_PRESSURE_LOAD_PER_CPU=6
Environment=GEOHOT_PRESSURE_MEMORY_FULL=60
Environment=GEOHOT_PRESSURE_IO_FULL=80
Environment=GEOHOT_PRESSURE_CPU_SOME=95
Environment=GEOHOT_PRESSURE_AVAILABLE_MIB=48
# 翻译指定的门：2026-11-07 的 .env 里钉着 12 个已死的模型键（workbuddy-cn-*、qoder-cn-*、
# qwenwork-*、trae-*），译文永远不 complete，读者面就停在凌晨那几条。这里是唯一健康的那扇门。
Environment=TRANSLATE_MODEL=dots3-note-prev
TimeoutStopSec=600
CONF
systemctl daemon-reload
systemctl restart geohot-exec-worker.service
sleep 3
echo "window=$mode slots=$slots conc=$conc"
systemctl show geohot-exec-worker.service -p Environment | tr ' ' '\n' | grep -E 'ANALYSIS_SLOTS|ANALYZE_CONCURRENCY' || true
SH
chmod 750 /usr/local/bin/geohot-exec-window.sh

cat > /etc/systemd/system/geohot-exec-window-day.service <<'UNIT'
[Unit]
Description=GeoHot executor day window (1 analysis slot)
[Service]
Type=oneshot
ExecStart=/usr/local/bin/geohot-exec-window.sh day
UNIT

cat > /etc/systemd/system/geohot-exec-window-night.service <<'UNIT'
[Unit]
Description=GeoHot executor night window (2 analysis slots)
[Service]
Type=oneshot
ExecStart=/usr/local/bin/geohot-exec-window.sh night
UNIT

cat > /etc/systemd/system/geohot-exec-window-day.timer <<'UNIT'
[Unit]
Description=Switch executor to day window at 07:00
[Timer]
OnCalendar=*-*-* 07:00:00
Persistent=true
[Install]
WantedBy=timers.target
UNIT

cat > /etc/systemd/system/geohot-exec-window-night.timer <<'UNIT'
[Unit]
Description=Switch executor to night window at 01:00
[Timer]
OnCalendar=*-*-* 01:00:00
Persistent=true
[Install]
WantedBy=timers.target
UNIT

systemctl daemon-reload
systemctl enable --now geohot-exec-window-day.timer geohot-exec-window-night.timer
/usr/local/bin/geohot-exec-window.sh day
systemctl list-timers 'geohot-*' --no-pager | head -6
echo WINDOW_OK
